public class SongTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        Song[] playlist = {
            new Song("Trance", 300), new Song("Zenith", 210),
            new Song("Breeze", 180), new Song("Anthem", 210)
        };
        java.util.Arrays.sort(playlist);
        check("sorted playlist", "[Breeze (180), Anthem (210), Zenith (210), Trance (300)]",
                java.util.Arrays.toString(playlist));
        Song shortSong = new Song("Short", 100);
        Song longSong = new Song("Long", 200);
        check("shorter song compares below", true, shortSong.compareTo(longSong) < 0);
        check("longer song compares above", true, longSong.compareTo(shortSong) > 0);
        Song alpha = new Song("Alpha", 150);
        Song beta = new Song("Beta", 150);
        check("tie broken alphabetically", true, alpha.compareTo(beta) < 0);
        check("reverse tie order", true, beta.compareTo(alpha) > 0);
        check("identical songs compare equal", 0, alpha.compareTo(new Song("Alpha", 150)));
        check("toString format", "Alpha (150)", alpha.toString());
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

